// Presentation for reconciled schedules, using the existing debt page's mobile layout.
const sum=ns=>ns.reduce((a,b)=>a+b,0);
const money=c=>(c/100).toLocaleString('en-US',{maximumFractionDigits:2});
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors=['#be185d','#6d28d9','#0369a1','#b45309','#047857','#4d7c0f','#bc5131','#58667d'];
const step=(n,title)=>'<h2><span class="debt-step">'+n+'</span>'+title+'</h2>';
const parts=(v,m,i,entries)=>v.parts.flatMap((t,part)=>{
 const due=t[2][m]||0;if(!due)return [];
 const applied=sum(entries.filter(x=>x.k===i&&x.part===part&&!x.inBaseline).map(x=>x.p));
 const used=Math.min(due,Math.max(0,applied-sum(t[2].slice(0,m))));
 return ['วันที่ '+t[1]+': '+money(due)+' บาท'+(used===due?' · จ่ายแล้ว ✓':used?' · เหลือ '+money(due-used)+' บาท':'')];
}).join(' / ');
const windowLabel=(p,m)=>{if(!p.payWindow)return '';const last=new Date(Date.UTC(+p.date.slice(0,4),+p.date.slice(5,7)+m,0)).getUTCDate();return p.payWindow.map(day=>Math.min(day,last)).join('–');};
const fundInfo=r=>!r.early?.length?'':'<p class="debt-hint">บิลที่ถึงกำหนดก่อนรอบจ่ายเดือนหน้า: '+r.early.map(t=>e(t.label)+' วันที่ '+t.day+' · '+money(t.n)+' บาท').join(' / ')+'<br>ต้องเตรียม '+money(sum(r.early.map(t=>t.n)))+' บาท · กันได้จากงบเดือนนี้ '+money(r.setAside)+' บาท'+(r.shortfall?' · <strong>ยังขาด '+money(r.shortfall)+' บาท</strong>':'')+'</p>';
const tag=s=>'<span class="debt-badge ok">'+s+'</span>';
export function renderDebtCards({s,p,ac,rows,paid,old,saved},editable){
 const credit=paid.slice(),groups=new Map();
 const schedule=rows.map((r,m)=>{const cells=r.a.map((target,i)=>{const done=Math.min(target,credit[i]);credit[i]-=done;return {i,target,done,left:target-done};}).filter(x=>x.target);return {...r,m,cells,left:sum(cells.map(x=>x.left))};});
 const now=schedule.find(x=>x.left>0),groupFor=ac.map((v,i)=>{const name=v.group||v.label;let g=groups.get(name);if(!g){g={name,idx:[],color:colors[groups.size%colors.length]};groups.set(name,g);}g.idx.push(i);return g;});
 const single=(v)=>!v.min&&v.bills.filter(x=>x>0).length===1&&!p.accounts[ac.indexOf(v)].carry;
 const endOf=(i)=>schedule.filter(r=>r.a[i]>0).at(-1)?.month||'';
 const groupCards=[...groups.values()].map(g=>{
  const start=sum(g.idx.map(i=>p.accounts[i].bal)),left=sum(g.idx.map(i=>ac[i].bal-paid[i])),done=start-left;
  const last=schedule.filter(r=>g.idx.some(i=>r.a[i]>0)).at(-1)?.month;
  const notes=g.idx.flatMap(i=>{const v=ac[i];if(v.parts.length)return v.parts.map((t,part)=>{
    const known=sum(s.entries.filter(x=>x.k===i&&!x.inBaseline&&x.part===part).map(x=>x.p));
    const assigned=sum(s.entries.filter(x=>x.k===i&&!x.inBaseline&&Number.isInteger(x.part)).map(x=>x.p));
    return e(t[0])+': หักวันที่ '+t[1]+(assigned===paid[i]&&v.bal===p.accounts[i].bal?' · เหลือ '+money(sum(t[2])-known):' · ยอดตามตาราง '+money(sum(t[2])))+' บาท';
   });
   return single(v)?['จ่ายครั้งเดียว · '+e(endOf(i))]:g.idx.length>1?[e(v.label)+(v.day?' · วันที่ '+v.day:'')+' · เหลือ '+money(v.bal-paid[i])+' บาท']:[];});
  return '<li style="--debt-color:'+g.color+'"><div class="debt-creditor-row"><b>'+e(g.name)+'</b><span class="debt-creditor-left"><strong>'+money(left)+'</strong> บาท</span></div><progress aria-label="ความคืบหน้า '+e(g.name)+'" max="'+(start||1)+'" value="'+done+'"></progress><div class="debt-creditor-row"><small>จ่ายแล้ว '+money(done)+' จาก '+money(start)+'</small>'+(left?'<small class="debt-close-plan">ปิด '+e(last)+'</small>':tag('ปิดแล้ว ✓'))+'</div>'+notes.map(n=>'<div><small>'+n+'</small></div>').join('')+'</li>';
 }).join('');
 const total=sum(p.accounts.map(v=>v.bal)),left=sum(ac.map((v,i)=>v.bal-paid[i])),done=total-left,pct=total?Math.floor(done*100/total):100;
 const nowDetail=now?'<p class="debt-lead">ยังขาดอีก <strong>'+money(now.left)+' บาท</strong> จากเป้า '+money(now.total)+' บาท'+(now.interest?'<br>ดอกเบี้ยที่เตรียมแยก (ประมาณ) <strong>'+money(now.interest)+' บาท</strong>':'')+'</p><ul class="debt-due">'+now.cells.map(x=>{const v=ac[x.i];return '<li style="--debt-color:'+groupFor[x.i].color+'"><div><b>'+e(v.label)+'</b>'+(v.day?'<small>วันที่ '+v.day+'</small>':'')+(v.parts.length?'<small>'+parts(v,now.m,x.i,s.entries)+'</small>':'')+(single(v)?'<small>จ่ายครั้งเดียว</small>':'')+'</div><div class="debt-due-amt">'+(x.left?'<strong>'+money(x.left)+'</strong><small>จาก '+money(x.target)+' บาท</small>':tag('ครบแล้ว ✓'))+'</div></li>';}).join('')+'</ul>':'<p>จ่ายครบทุกงวดแล้ว ✓</p>';
 const form='<form id="debt-payment-form" class="debt-entry-form"><label>จ่ายให้ใคร<select id="debt-creditor" required><option value="">เลือกเจ้าหนี้</option>'+ac.map((v,i)=>'<option value="'+i+'">'+e(v.label)+' · เหลือ '+money(v.bal-paid[i])+' บาท</option>').join('')+'</select></label><label>จ่ายไปทั้งหมด (บาท)<input id="debt-payment-amount" inputmode="decimal" type="number" min=".01" step=".01" required></label><label>ในนั้นเป็นดอกเบี้ย<input id="debt-payment-interest" inputmode="decimal" type="number" min="0" step=".01" value="0"><span class="debt-field-hint">ไม่มีใส่ 0</span></label><label>ในนั้นเป็นค่าประกัน<input id="debt-payment-fee" inputmode="decimal" type="number" min="0" step=".01" value="0"><span class="debt-field-hint">หรือค่าธรรมเนียม</span></label><button class="button primary">บันทึกการจ่าย</button></form><p id="debt-payment-error" role="alert" hidden></p>';
 const monthly=schedule.map(r=>'<details class="debt-month'+(r===now?' now':!r.left?' done':'')+'"'+(r===now?' open':'')+'><summary><span class="debt-month-name">'+(p.payWindow?windowLabel(p,r.m)+' ':'')+r.month+'</span><span class="debt-month-status">'+(!r.left?'ครบแล้ว ✓':(r===now?'งวดนี้ · ':'')+'ขาด '+money(r.left))+'</span><span class="debt-month-total">'+money(r.total)+' บาท</span></summary><table><thead><tr><th scope="col">เจ้าหนี้</th><th scope="col">เป้า</th><th scope="col">จ่ายแล้ว</th><th scope="col">ขาด</th></tr></thead><tbody>'+r.cells.map(x=>{const v=ac[x.i];return '<tr><th scope="row"><i style="background:'+groupFor[x.i].color+'"></i>'+e(v.label)+(v.day?'<small>วันที่ '+v.day+'</small>':'')+(v.parts.length?'<small>'+parts(v,r.m,x.i,s.entries)+'</small>':'')+(single(v)?'<small>จ่ายครั้งเดียว</small>':'')+'</th><td>'+money(x.target)+'</td><td>'+money(x.done)+'</td><td>'+money(x.left)+'</td></tr>';}).join('')+'</tbody></table><p class="debt-hint">ใช้จากงบเดือนนี้ '+money(r.fromBudget)+' บาท'+(r.setAside?' · กันไว้เดือนหน้า '+money(r.setAside)+' บาท':'')+(r.carryIn?' · ใช้เงินที่กันไว้ '+money(r.carryIn)+' บาท':'')+' · ดอกประมาณ '+money(r.interest)+' บาท</p>'+fundInfo(r)+'</details>').join('');
 const hist=[...old.map(x=>({at:x.at,label:x.creditor+' · แผนเดิม',p:x.amountCents,i:x.interestCents||0,f:x.feeCents||0})),...s.entries.map(x=>({...x,label:ac[x.k].label}))].sort((a,b)=>String(b.at||'').localeCompare(String(a.at||'')));
 const history='<details class="debt-section debt-history" id="debt-history"><summary>'+step(5,'ประวัติการจ่าย <small>'+hist.length+' รายการ</small>')+'<span class="debt-history-peek">จ่ายจริงรวม '+money(sum(hist.map(x=>x.p+x.i+x.f)))+' บาท รวมประวัติเดิม</span></summary><ul>'+hist.map(x=>'<li style="--debt-color:#74839c"><div class="debt-history-main"><b>'+e(x.label)+'</b><span>'+(x.at?new Date(x.at).toLocaleDateString('th-TH',{timeZone:'Asia/Bangkok'}):'จากสถานะเดิม')+'</span><small>ลดหนี้ '+money(x.p)+(x.i?' · ดอก '+money(x.i):'')+(x.f?' · ค่าธรรมเนียม '+money(x.f):'')+(x.inBaseline?' · รวมอยู่ในยอดที่ยืนยันแล้ว':'')+'</small></div><strong>'+money(x.p+x.i+x.f)+'</strong>'+(x.id?'<button class="debt-remove" data-action="debt-remove" data-id="'+e(x.id)+'" aria-label="ลบรายการจ่าย">✕</button>':'')+'</li>').join('')+'</ul></details>';
 const quick=ac.map((v,i)=>single(v)&&v.bal>paid[i]?'<small>'+e(v.label)+' · '+money(v.bal-paid[i])+' บาท · จ่ายครั้งเดียว '+(p.payWindow&&!v.day?windowLabel(p,schedule.findIndex(r=>r.a[i]>0))+' ':'')+endOf(i)+'</small>':'').filter(Boolean).join('');
 return '<div class="debt-page"><header class="debt-bar"><div><span class="debt-bar-tag">เครื่องมือส่วนตัว · ไม่เกี่ยวกับการเรียน</span><h1>แผนจัดการหนี้</h1><p>งบเดือนละ '+money(p.budget)+' บาท'+(rows.length?' · '+rows[0].month+' ถึง '+rows.at(-1).month:'')+'</p></div><a class="button secondary" href="#home">← กลับห้องเรียน</a></header>'+
 (!saved?'<section class="debt-section"><b>ใช้แผนนี้กับประวัติเดิม</b> <button class="button primary" data-action="debt-activate" '+(editable?'':'disabled')+'>ใช้แผนนี้</button></section>':'')+
 '<section class="debt-hero" aria-label="ภาพรวมหนี้"><div class="debt-hero-main"><span>หนี้คงเหลือ</span><p class="debt-balance">'+money(left)+' <small>บาท</small></p><div class="debt-meter"><progress aria-label="ความคืบหน้าการจ่าย" max="100" value="'+pct+'"></progress><b>'+pct+'%</b></div><small>หักจากยอดตั้งต้นแผนนี้แล้ว '+money(done)+' จาก '+money(total)+' บาท</small>'+quick+'</div><dl class="debt-hero-facts"><div><dt>จ่ายครบแล้ว</dt><dd>'+schedule.filter(r=>!r.left).length+' <small>/ '+rows.length+' เดือน</small></dd></div><div><dt>งวดที่ต้องจ่ายตอนนี้</dt><dd>'+(now?now.month:'ครบทุกงวด ✓')+'</dd></div><div><dt>ปิดหนี้ทั้งหมดตามแผน</dt><dd>'+(rows.at(-1)?.month||'ปิดแล้ว')+'</dd></div></dl></section>'+
 '<section class="debt-section debt-now">'+step(1,now?(p.payWindow?'รอบจ่าย '+windowLabel(p,now.m)+' ':'ต้องจ่ายงวด ')+now.month:'งวดนี้')+nowDetail+(now?fundInfo(now):'')+'</section>'+
 (saved?'<section class="debt-section debt-entry-panel">'+step(2,'จ่ายแล้ว? บันทึกตรงนี้')+'<p>จ่ายทีละเท่าไรก็ได้ ระบบรวมยอดให้เอง</p>'+form+'</section>':'')+
 '<section class="debt-section">'+step(3,'แผนทั้ง '+rows.length+' เดือน')+'<p>แตะเดือนเพื่อดูยอดของแต่ละเจ้า</p><div class="debt-months">'+monthly+'</div></section>'+
 '<section class="debt-section">'+step(4,'ยอดคงเหลือแต่ละเจ้า')+'<ul class="debt-creditors">'+groupCards+'</ul></section>'+history+
 '<details class="debt-more"><summary>ดอกเบี้ยและวิธีคิด</summary><p>'+e(p.note)+'</p><p>ประมาณดอกรอบละ 30 วัน: '+ac.filter(v=>v.period).map(v=>e(v.label)+' '+v.rate+'% ต่อ'+(v.period==='m'?'เดือน':'ปี')).join(' · ')+'</p><p>ยอดที่ยืนยันใหม่รวมการจ่ายก่อนวันปรับยอดแล้ว ดูประวัติทั้งหมดได้ที่ข้อ 5</p></details></div>';
}
